package com.angle.trading.security;import jakarta.servlet.http.HttpServletRequest;import jakarta.servlet.http.HttpServletResponse;import org.slf4j.Logger;import org.slf4j.LoggerFactory;import org.springframework.security.core.Authentication;import org.springframework.security.web.authentication.logout.LogoutSuccessHandler;import org.springframework.stereotype.Component;import java.io.IOException;import java.time.LocalDateTime;@Componentpublic class CustomLogoutSuccessHandler implements LogoutSuccessHandler {    private static final Logger log =            LoggerFactory.getLogger(CustomLogoutSuccessHandler.class);    @Override    public void onLogoutSuccess(HttpServletRequest request,                                HttpServletResponse response,                                Authentication authentication)            throws IOException {        if (authentication != null) {            log.info("User '{}' logged out at {}",                    authentication.getName(),                    LocalDateTime.now().withNano(0));        }        response.sendRedirect("/auth/login?logout");    }}